import{_ as p,r as s,o,c as l,e as n,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"File Attachments - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":3,"title":"Creating new attachments","slug":"creating-new-attachments","link":"#creating-new-attachments","children":[]},{"level":3,"title":"Viewing attachments","slug":"viewing-attachments","link":"#viewing-attachments","children":[]},{"level":3,"title":"Usage example","slug":"usage-example","link":"#usage-example","children":[]},{"level":3,"title":"Validation example","slug":"validation-example","link":"#validation-example","children":[]}],"relativePath":"1.x/database/attachments.md","filePath":"1.x/database/attachments.md"}'),r={name:"1.x/database/attachments.md"};function u(k,a,d,g,h,m){const t=s("pre-heading"),e=s("post-heading");return o(),l("div",null,[n(t),a[0]||(a[0]=c("h1",null,"File Attachments",-1)),n(e),a[1]||(a[1]=i(`<p>Models can support file attachments using a subset of the <a href="./../database/relations.html#polymorphic-relations">polymorphic relationship</a>. The <code>$attachOne</code> or <code>$attachMany</code> relations are designed for linking a file to a database record called &quot;attachments&quot;. In almost all cases the <code>System\\Models\\File</code> model is used to safekeep this relationship where reference to the files are stored as records in the <code>system_files</code> table and have a polymorphic relation to the parent model.</p><p>In the examples below the model has a single Avatar attachment model and many Photo attachment models.</p><p>A single file attachment:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;avatar&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;System\\Models\\File&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Multiple file attachments:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;photos&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;System\\Models\\File&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>NOTE:</strong> If you have a column in your model&#39;s table with the same name as the attachment relationship it will not work. Attachments and the FileUpload FormWidget work using relationships, so if there is a column with the same name present in the table itself it will cause issues.</p></blockquote><p>Protected attachments are uploaded to the application&#39;s <strong>uploads/protected</strong> directory which is not accessible for the direct access from the Web. A protected file attachment is defined by setting the <em>public</em> argument to <code>false</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;avatar&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;System\\Models\\File&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;public&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="creating-new-attachments"><a href="#creating-new-attachments" class="header-anchor">#</a> Creating new attachments</h3><p>For singular attach relations (<code>$attachOne</code>), you may create an attachment directly via the model relationship, by setting its value using the <code>Input::file</code> method, which reads the file data from an input upload.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also pass a string to the <code>data</code> attribute that contains an absolute path to a local file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;/path/to/somefile.jpg&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Sometimes it may also be useful to create a <code>File</code> instance directly from (raw) data:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$file</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified">System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromData</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Some content&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;sometext.txt&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>For multiple attach relations (<code>$attachMany</code>), you may use the <code>create</code> method on the relationship instead, notice the file object is associated to the <code>data</code> attribute. This approach can be used for singular relations too, if you prefer.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">avatar</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;data&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Alternatively, you can prepare a File model before hand, then manually associate the relationship later. Notice the <code>is_public</code> attribute must be set explicitly using this approach.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$file</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified">System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">data</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">is_public</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">avatar</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$file</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can also add a file from a URL. To work this method, you need install cURL PHP Extension.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$file</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified">System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">fromUrl</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;https://example.com/uploads/public/path/to/avatar.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">avatar</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$file</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Occasionally you may need to change a file name. You may do so by using second method parameter.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">fromUrl</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;https://example.com/uploads/public/path/to/avatar.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;somefilename.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="viewing-attachments"><a href="#viewing-attachments" class="header-anchor">#</a> Viewing attachments</h3><p>The <code>getPath</code> method returns the full URL of an uploaded public file. The following code would print something like <strong>example.com/uploads/public/path/to/avatar.jpg</strong></p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">getPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Returning multiple attachment file paths:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">photos</span> <span class="token keyword">as</span> <span class="token variable">$photo</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$photo</span><span class="token operator">-&gt;</span><span class="token function">getPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>getLocalPath</code> method will return an absolute path of an uploaded file in the local filesystem.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">getLocalPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To output the file contents directly, use the <code>output</code> method, this will include the necessary headers for downloading the file:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">output</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can resize an image with the <code>getThumb</code> method. The method takes 3 parameters - image width, image height and the options parameter. Read more about these parameters on the <a href="./../services/image-resizing.html#resize-parameters">Image Resizing</a> page.</p><h3 id="usage-example"><a href="#usage-example" class="header-anchor">#</a> Usage example</h3><p>This section shows a full usage example of the model attachments feature - from defining the relation in a model to displaying the uploaded image on a page.</p><p>Inside your model define a relationship to the <code>System\\Models\\File</code> class, for example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;featured_image&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;System\\Models\\File&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Build a form for uploading a file:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;files&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>example_file<span class="token punctuation">&quot;</span></span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>file<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Upload File<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>Process the uploaded file on the server and attach it to a model:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Find the Blog Post model</span>
<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Save the featured image of the Blog Post model</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">hasFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;example_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">featured_image</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;example_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Alternatively, you can use <a href="./../database/relations.html#deferred-binding">deferred binding</a> to defer the relationship:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Find the Blog Post model</span>
<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Look for the postback data &#39;example_file&#39; in the HTML form above</span>
<span class="token variable">$fileFromPost</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;example_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// If it exists, save it as the featured image with a deferred session key</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$fileFromPost</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">featured_image</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;data&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$fileFromPost</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Display the uploaded file on a page:</p><div class="language-php extra-class"><pre class="language-php"><code>// Find the Blog Post model again
$post = Post::find(1);

// Look for the featured image address, otherwise use a default one
if ($post-&gt;featured_image) {
    $featuredImage = $post-&gt;featured_image-&gt;getPath();
}
else {
    $featuredImage = &#39;http://placehold.it/220x300&#39;;
}

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$featuredImage</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">alt</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Featured Image<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>If you need to access the owner of a file, you can use the <code>attachment</code> property of the <code>File</code> model:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$morphTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;attachment&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">attachment</span><span class="token punctuation">;</span>
</code></pre></div><p>For more information read the <a href="./../database/relations.html#polymorphic-relations">polymorphic relationships</a></p><h3 id="validation-example"><a href="#validation-example" class="header-anchor">#</a> Validation example</h3><p>The example below uses <a href="./../services/validation.html#validating-arrays">array validation</a> to validate <code>$attachMany</code> relationships.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Model</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Gallery</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package">Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$attachMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;photos&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">File</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;photos&#39;</span>   <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;photos.*&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;image|max:1000|dimensions:min_width=100,min_height=100&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token comment">/* some other code */</span>
<span class="token punctuation">}</span>
</code></pre></div><p>For more information on the <code>attribute.*</code> syntax used above, see <a href="./../services/validation.html#validating-arrays">validating arrays</a>.</p>`,55))])}const y=p(r,[["render",u]]);export{v as __pageData,y as default};
